export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioOutput {
  results: Result[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function quotePremium(items: Item[]): number {
  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE;
  return policyBase + firstInsurance + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium((step as QuoteStep).items),
    })),
  };
}

