const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE = 0.1;

/** Every component costs the same, whatever its kind. */
const COMPONENT_BASE_PREMIUM = 25;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};

/** Premiums round up: the MHPCO's favour is the larger amount. */
const roundPremium = Math.ceil;

function quotePremium(items: Item[]): number {
  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE;
  return roundPremium(policyBase + firstInsurance + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium((step as QuoteStep).items),
    })),
  };
}

