    it("3 runes → 60 G base premium (block applies) (+6 first insurance +5 fee = 71 G)", () => {
      expect(premiumFor([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(71);
    });
    it("4 runes → 100 G base premium (no block — block requires exactly 3) (+10 +5 = 115 G)", () => {
      const fourRunes: Item[] = Array.from({ length: 4 }, () => ({ type: "rune" }));

      expect(premiumFor(fourRunes)).toBe(115);
    });
    it("7 runes → 175 G base premium (no stacked blocks) (+17.5 +5 = 197.5 → 198 G)", () => {
      const sevenRunes: Item[] = Array.from({ length: 7 }, () => ({ type: "rune" }));

      expect(premiumFor(sevenRunes)).toBe(198);
    });
    it("2 runes + 1 moonstone → 75 G base premium (no block: different types) (+7.5 +5 = 87.5 → 88 G)", () => {
      expect(premiumFor([{ type: "rune" }, { type: "rune" }, { type: "moonstone" }])).toBe(88);
    });
    it("3 runes + 3 moonstones → 120 G base premium (two separate blocks) (+12 +5 = 137 G)", () => {
      const items: Item[] = [
        ...Array.from({ length: 3 }, () => ({ type: "rune" })),
        ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
      ];

      expect(premiumFor(items)).toBe(137);
    });
  });

  describe("quote — item-specific modifiers", () => {
    it("cursed sword adds 50 % of that item's base premium (100 base + 50 curse + 10 first insurance + 5 fee = 165 G)", () => {
      expect(premiumFor([{ type: "sword", cursed: true }])).toBe(165);
    });
    it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → 20 % loyalty discount applies");
    it.todo("customer with 1 year → no loyalty discount");
    it.todo("first insurance surcharge of 10 % of the policy base premium applies");
    it.todo("second contract in a scenario → 15 % follow-up discount on the policy base premium");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo(
      "cursed sword + plain amulet → policy base 160 G, curse surcharge 50 G (of the sword only) → 210 G before further modifiers and fee",
    );
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("premium of 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo(
      "newcomer (0 years, no previous contract) with a cursed sword (steel, enchantment 3) → premium 165 G",
    );
    it.todo(
      "long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G",
    );
  });

  describe("quote — errors", () => {
    it.todo("item with an unknown type (e.g. broomstick) → error, no results");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("rune (insurance value 250 G), damage 200 G → payout 100 G (no special clause)");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (100 G deductible per damaged item)",
    );
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("policy with sword + amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("policy with a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("policy with sword + 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword policy, second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries → each treated as a separate damage with its own deductible");
    it.todo("more damage entries of a type than the policy covers → error, whole claim rejected");
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("payout of 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — errors", () => {
    it.todo("damage to an item not part of the policy (amulet when only a sword is insured) → error");
    it.todo("damage entry with an unknown item type → error");
    it.todo("damage entry with amount -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes {results} JSON to stdout");
    it.todo("exits with a non-zero status code and writes an error description to stderr on invalid input");
  });
