export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioOutput {
  results: Result[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE = 0.1;

/** Every component costs the same, whatever its kind. */
const COMPONENT_BASE_PREMIUM = 25;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};

/** Premiums round up: the MHPCO's favour is the larger amount. */
const roundPremium = Math.ceil;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

/** Base premium for all items of one type, honouring the block discount. */
function typeBasePremium(type: string, count: number): number {
  if (count === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
  return count * BASE_PREMIUMS[type];
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

const CURSE_SURCHARGE = 0.5;

/** Item-specific surcharges apply to the affected item's own base premium. */
function itemSurcharges(item: Item): number {
  return item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE : 0;
}

function quotePremium(items: Item[]): number {
  const policyBasePremium = [...countByType(items)].reduce(
    (sum, [type, count]) => sum + typeBasePremium(type, count),
    0,
  );
  const surcharges = items.reduce((sum, item) => sum + itemSurcharges(item), 0);
  // Policy-wide modifiers apply to the policy base premium — the sum of the
  // item base premiums, before any item-specific surcharges.
  const firstInsurance = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
  return roundPremium(policyBasePremium + surcharges + firstInsurance + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium((step as QuoteStep).items),
    })),
  };
}

