    it.todo(
      "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (100 G deductible per damaged item)",
    );
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("policy with sword + amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("policy with a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("policy with sword + 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword policy, second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  });

  describe("claim — multiple items of the same type", () => {
